// The report route's answer: a job run's or a campaign run's report
// regenerated by hand over the socket, refused or accepted exactly as the
// Regenerate button would be (convention §7.3.2, §8.3).

import { campaign_run, job_run } from '@shared/world'
import { primary_report_path } from '../engine/report_paths'
import type { AgentDeps, AgentResponse } from './answer'
import { failure, json } from './answer'

/**
 * Accepted is `202`, at once: the report is due, not done. A report script may
 * run for the whole report timeout — ten minutes — which no caller should
 * hold a connection for, and which the 30-second wait on a write (§43.3) and
 * the MCP binary's own timeout were never sized for. The run reads
 * `report_running` in `GET /jobs/{name}` or `GET /campaigns/{name}` until the
 * outcome lands there.
 *
 * A body of `{"members": true}` asks a campaign run for every member's report
 * first, then its own (§8.3); none, or `false`, for its own alone. The
 * campaign run reads `report_running` through both stages.
 */
export function rerun_report(
  name: string,
  run_id: string,
  body: string,
  deps: AgentDeps
): AgentResponse {
  let members: unknown
  try {
    members = (JSON.parse(body === '' ? '{}' : body) as { members?: unknown }).members
  } catch (error) {
    return failure(400, (error as Error).message)
  }
  if (members !== undefined && typeof members !== 'boolean') {
    return failure(400, '`members` is true or false')
  }

  const world = deps.current_world()
  const entity = world.entities.find((candidate) => candidate.name === name)
  if (entity === undefined) {
    return failure(404, `No such entity: ${name}`)
  }
  const run =
    entity.kind === 'Job'
      ? job_run(world, entity.id, run_id)
      : campaign_run(world, entity.id, run_id)
  if (run === undefined) {
    return failure(404, `No such run: ${name} run ${run_id}`)
  }
  if (members === true && entity.kind === 'Job') {
    return failure(400, `${name} is a Job; only a Campaign run has members`)
  }

  const result = deps.rerun_report({
    entity_id: entity.id,
    run_id,
    ...(members === true ? { members } : {})
  })
  // The workbench's own refusal, unchanged: not eligible, or already running.
  if (!result.ok) {
    return failure(400, result.message)
  }
  return json(202, {
    run_id,
    report_running: true,
    location: { report: primary_report_path(entity.id, run_id) },
    follow: `/${entity.kind === 'Job' ? 'jobs' : 'campaigns'}/${name}`
  })
}
